<div class="d-flex justify-content-between mb-4"><h1><?= $staff?'Payments':'My payments'?></h1><?php if($staff):?><a class="btn btn-primary" href="<?=e(url('/finance/payments/create'))?>">Record manual payment</a><?php endif;?></div>
<?php if($staff&&$create):?><form method="post" action="<?=e(url('/finance/payments'))?>" class="card card-body mb-4"><?=csrf_field()?><label class="form-label">Invoice</label><select name="invoice_number" class="form-select" required><?php foreach($invoices as $i)if($i['balance_due']!=='0.00'):?><option value="<?=e($i['invoice_number'])?>"><?=e($i['invoice_number'].' — '.$i['member_name'].' — '.$i['currency'].' '.$i['balance_due'])?></option><?php endif;?></select><div class="row g-3 mt-1"><div class="col-md-3"><label class="form-label">Amount</label><input name="amount" class="form-control" required></div><div class="col-md-2"><label class="form-label">Currency</label><input name="currency" value="ZAR" class="form-control" maxlength="3" required></div><div class="col-md-3"><label class="form-label">Method</label><select name="payment_method" class="form-select"><option value="eft">EFT</option><option value="cash">Cash</option><option value="card_manual">Card (manual)</option><option value="other_manual">Other manual</option></select></div><div class="col-md-4"><label class="form-label">Manual reference</label><input name="manual_reference" class="form-control" required></div><div class="col-md-4"><label class="form-label">Received at</label><input type="datetime-local" name="received_at" class="form-control"></div><div class="col-md-8"><label class="form-label">Safe note</label><input name="note" maxlength="1000" class="form-control"></div></div><p class="small text-muted mt-3">This records a transaction reported through an external/manual channel; it does not process money.</p><button class="btn btn-primary">Confirm and record payment</button></form><?php endif;?>
<div class="table-responsive"><table class="table"><thead><tr><th>Payment</th><th>Invoice</th><th>Amount</th><th>Method</th><th>Received</th><th>Status</th><?php if($staff):?><th>Correction</th><?php endif;?></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><a href="<?=e(url('/finance/payments/'.$p['payment_reference'].'/receipt'))?>"><?=e($p['payment_reference'])?></a></td><td><?=e($p['invoice_number']??'—')?></td><td><?=e($p['currency'].' '.$p['amount'])?></td><td><?=e(str_replace('_',' ',$p['payment_method']))?></td><td><?=e($p['received_at'])?></td><td><?=e($p['status'])?></td><?php if($staff):?><td><?php if($p['status']==='completed'):?><form method="post" action="<?=e(url('/finance/payments/'.$p['payment_reference'].'/reverse'))?>"><?=csrf_field()?><input name="reason" minlength="10" placeholder="Reversal reason" required class="form-control form-control-sm mb-1"><button class="btn btn-sm btn-outline-danger">Record reversal</button></form><?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div>
